"""Render a self-contained interactive development report from cascade ensembles."""
import argparse,json
from pathlib import Path
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('reports',nargs='+');parser.add_argument('--output',required=True)
args=parser.parse_args();datasets=[]
for filename in args.reports:
 r=json.loads(Path(filename).read_text())
 datasets.append({'name':'Coherence '+('on' if r['settings'][0]['enabled'] else 'off'),
  'analysis_versions':r.get('analysis_versions',{}),'attempted':r['events_per_generator'],'settings':r['settings'][0],'selection':r['selection'],
  'comparisons':r['comparisons'],'scope':r['scope'],'normalization':r['normalization'],'uncertainty':r['uncertainty'],
  'cpp':{k:v for k,v in r['cpp'].items() if k!='events'},'reference':{k:v for k,v in r['reference'].items() if k!='events'},
  'events':[{tag:{k:v for k,v in r[tag]['events'][i].items() if k!='histograms'} for tag in ['cpp','reference']} for i in range(r['events_per_generator'])],
  'input_sha256':r['input_sha256'],'guard_source_sha256':r['guard_source_sha256']})
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>JEWEL C++ cascade validation</title>
<style>
body{font:16px system-ui,sans-serif;line-height:1.5;color:#18252b;background:#f3f6f7;margin:0}main{max-width:1100px;margin:auto;padding:32px 22px}h1{font-size:32px;margin-bottom:8px}h2{font-size:21px}.note{border-left:4px solid #c58a32;background:#fff7e8;padding:14px 18px}.panel{background:white;border:1px solid #dbe2e6;border-radius:10px;padding:18px;margin:18px 0}.cards{display:flex;gap:16px;flex-wrap:wrap}.card{flex:1;min-width:180px;background:white;padding:16px;border-radius:8px;border:1px solid #dbe2e6}.number{font-size:25px;font-weight:650}.muted{color:#53636b;font-size:14px}label{display:inline-block;margin:0 20px 12px 0}select,input,button{font:inherit;padding:6px 10px;border:1px solid #9eafb6;border-radius:5px;background:white}svg{width:100%;height:auto}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:right;padding:7px;border-bottom:1px solid #e0e7ea}th:first-child,td:first-child{text-align:left}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.teal{color:#007f85}.orange{color:#b25d13}.warn{color:#9c4c00}.good{color:#176c43}.scroll{overflow:auto}
</style><main><p class="muted">DEVELOPMENT CHECKPOINT · CONTROLLED PARTON CASCADES</p><h1>JEWEL C++ cascade validation</h1>
<p>Compare the C++ shower engine with the frozen JEWEL 2.6.0 physics routines.</p>
<div class="note"><strong>Full generator validation is unfinished.</strong> These inputs are a controlled 100 GeV parent split, not Pythia-generated dijet events. There is no hadronization. The diagnostic Fortran scheduler stops at nonfinite branch states; its physics routines are unchanged. These results do not establish the final full-feature acceptance goal.</div>
<div class="panel"><label>Setting <select id="setting"></select></label><label>Observable <select id="observable"><option value="pt">Jet pT</option><option value="girth">Girth (eta–phi)</option><option value="ptd">pTD</option></select></label><p id="selection" class="muted"></p></div>
<div id="cards" class="cards"></div><div class="panel"><p><b class="teal">C++</b> &nbsp; <b class="orange">Fortran</b> <span class="muted">· jets per attempted event per bin</span></p><svg id="plot" viewBox="0 0 960 520" role="img" aria-label="Jet observable distributions and C++ to Fortran ratio"></svg><p class="muted">Ratio bars show 95% intervals from paired event-level delta-method errors. The shaded band is 0.9–1.1. Sparse bins are displayed, not hidden. This plot is diagnostic, not an automatic acceptance certificate.</p><div class="scroll"><table><thead><tr><th>Bin</th><th>C++ jets</th><th>Fortran jets</th><th>Ratio</th><th>Standard error</th><th>Assessment</th></tr></thead><tbody id="bins"></tbody></table></div></div>
<div class="panel"><h2>Event outcomes</h2><label>Show <select id="eventFilter"><option value="all">All attempts</option><option value="failed">Rejected / invalid</option><option value="different">Different jet counts</option></select></label><label>Seed <input id="seed" placeholder="Filter by seed"></label><button id="previous">Previous</button> <button id="next">Next</button><p id="page" class="muted"></p><div class="scroll"><table><thead><tr><th>Seed</th><th>C++ outcome</th><th>Fortran outcome</th><th>C++ jets</th><th>Fortran jets</th><th>C++ draws</th><th>Fortran draws</th></tr></thead><tbody id="events"></tbody></table></div></div>
<details class="panel"><summary>Definitions and provenance</summary><p>Final shower partons have status 4 or 5. Status-3 medium recoils are excluded. Anti-kt clustering uses hepyy/cppyy FastJet; selection is applied after clustering. Girth is Σ pT,i ΔRηφ,i / Σ pT,i. pTD is √Σ pT,i² / Σ pT,i.</p><p>Invalid and discarded attempts contribute zero jets. Unit weights are used; this is not a cross-section prediction. Error estimates use paired attempts and keep jet correlations within each event. Empty reference bins have undefined ratios.</p><pre id="provenance"></pre></details></main>
<script id="data" type="application/json">__DATA__</script><script>
const datasets=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id);let page=0;
datasets.forEach((d,i)=>{$('setting').add(new Option(d.name,i));});
function svg(tag,attrs,text){const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;$('plot').appendChild(e);return e;}
function fmt(x){return x===null?'—':Number(x).toPrecision(4);}
function row(parent,values){const tr=document.createElement('tr');for(const value of values){const td=document.createElement('td');td.textContent=value;tr.appendChild(td);}parent.appendChild(tr);}
function outcomes(){const d=datasets[$('setting').value],filter=$('eventFilter').value,seed=$('seed').value;const rows=d.events.filter(e=>String(e.cpp.seed).includes(seed)&&(filter==='all'||filter==='failed'&&(!e.cpp.accepted||!e.reference.accepted)||filter==='different'&&e.cpp.jets.length!==e.reference.jets.length));page=Math.max(0,Math.min(page,Math.ceil(rows.length/20)-1));$('events').replaceChildren();for(const e of rows.slice(page*20,page*20+20)){const state=x=>x.accepted?'Accepted':x.invalid?'Invalid ('+x.invalid+')':'Discarded';row($('events'),[e.cpp.seed,state(e.cpp),state(e.reference),e.cpp.jets.length,e.reference.jets.length,e.cpp.draws,e.reference.draws]);}$('page').textContent=rows.length+' matching attempts · page '+(page+1)+' / '+Math.max(1,Math.ceil(rows.length/20));}
function render(){const d=datasets[$('setting').value],key=$('observable').value,bins=d.comparisons[key];$('cards').replaceChildren();for(const [name,value] of [['Attempts per engine',d.attempted],['Accepted C++ / Fortran',d.cpp.accepted+' / '+d.reference.accepted],['Selected jets C++ / Fortran',d.cpp.selected_jets+' / '+d.reference.selected_jets]]){const c=document.createElement('div');c.className='card';const number=document.createElement('div');number.className='number';number.textContent=value;const label=document.createElement('div');label.className='muted';label.textContent=name;c.append(number,label);$('cards').append(c);}
$('selection').textContent='Anti-kt R = 0.4 · pT ≥ 5 GeV · |eta| < 2 · KINMODE '+d.settings.kinmode+' · rate multiplier '+d.settings.cross+' · SCATRECOIL = false';
$('plot').replaceChildren();const left=75,right=925,xmin=bins[0].low,xmax=bins.at(-1).high,x=v=>left+(v-xmin)/(xmax-xmin)*(right-left),max=Math.max(1/d.attempted,...bins.flatMap(b=>[b.cpp/d.attempted,b.reference/d.attempted]))*1.12,y=v=>270-v/max*235,ratioMax=Math.max(1.4,...bins.filter(b=>b.ratio!==null).map(b=>b.ratio+1.96*b.paired_standard_error)),ry=v=>465-v/ratioMax*140;
for(let t=0;t<=4;t++){const v=max*t/4;svg('line',{x1:left,x2:right,y1:y(v),y2:y(v),stroke:'#e1e7ea'});svg('text',{x:65,y:y(v)+4,'text-anchor':'end',fill:'#53636b','font-size':12},v.toFixed(3));}
for(let t=0;t<=4;t++){const v=ratioMax*t/4;svg('text',{x:65,y:ry(v)+4,'text-anchor':'end',fill:'#53636b','font-size':12},v.toFixed(2));}
svg('rect',{x:left,y:ry(1.1),width:right-left,height:ry(.9)-ry(1.1),fill:'#e0f1e7'});svg('line',{x1:left,x2:right,y1:ry(1),y2:ry(1),stroke:'#718778','stroke-dasharray':'4 3'});svg('text',{x:12,y:345,fill:'#53636b','font-size':12},'Ratio');
for(const [tag,color]of [['cpp','#007f85'],['reference','#b25d13']]){const points=bins.flatMap(b=>[[x(b.low),y(b[tag]/d.attempted)],[x(b.high),y(b[tag]/d.attempted)]]).map(p=>p.join(',')).join(' ');svg('polyline',{points,fill:'none',stroke:color,'stroke-width':2});}
for(const b of bins){const cx=x((b.low+b.high)/2);svg('text',{x:x(b.low),y:490,'text-anchor':'middle',fill:'#53636b','font-size':12},b.low);if(b.ratio!==null){const err=1.96*b.paired_standard_error;svg('line',{x1:cx,x2:cx,y1:ry(Math.min(ratioMax,b.ratio+err)),y2:ry(Math.max(0,b.ratio-err)),stroke:'#18252b'});const circle=svg('circle',{cx,cy:ry(Math.min(ratioMax,b.ratio)),r:4,fill:'#007f85'});const title=document.createElementNS('http://www.w3.org/2000/svg','title');title.textContent=b.low+'–'+b.high+': '+fmt(b.ratio)+' ± '+fmt(err);circle.appendChild(title);}}
svg('text',{x:500,y:516,'text-anchor':'middle',fill:'#18252b','font-size':14},key==='pt'?'Jet pT [GeV]':key==='ptd'?'pTD':'Girth');$('bins').replaceChildren();for(const b of bins){let verdict=b.ratio===null?'No reference jets':Math.min(b.cpp,b.reference)<25?'Sparse':Math.abs(b.ratio-1)>.1?'Outside ±10%':Math.abs(b.ratio-1)+1.96*b.paired_standard_error<=.1?'Within band (95% interval)':'Within band; precision limited';row($('bins'),[b.low+'–'+b.high,b.cpp,b.reference,fmt(b.ratio),fmt(b.paired_standard_error),verdict]);}
$('provenance').textContent=JSON.stringify({scope:d.scope,analysis_versions:d.analysis_versions,settings:d.settings,selection:d.selection,input_sha256:d.input_sha256,guard_source_sha256:d.guard_source_sha256,cpp:d.cpp,reference:d.reference},null,2);outcomes();}
$('setting').onchange=()=>{page=0;render();};$('observable').onchange=render;$('eventFilter').onchange=()=>{page=0;outcomes();};$('seed').oninput=()=>{page=0;outcomes();};$('previous').onclick=()=>{page--;outcomes();};$('next').onclick=()=>{page++;outcomes();};render();
</script></html>'''
html=html.replace('__DATA__',json.dumps(datasets,allow_nan=False).replace('<','\\u003c'))
Path(args.output).write_text(html)
print(args.output)
